21	// DEVDESK-47 step 6: the header (Est. cost, Billed, Unattributed), the footer
22	// price hint, and the help section. Names assumed from the plan: Model.cost
23	// (pricing.Summary, stored by withRows); header keys "Est. cost", "Billed",
24	// "Unattributed"; help section titled "Costs". pricesYAML is cost_test.go's:
25	// model-a {1, 10, 2, 4, 0.1}, model-b {2, 20, 4, 8, 0.2} USD per million.
26	
27	const (
28		estKey          = "Est. cost"
29		billedKey       = "Billed"
30		unattributedKey = "Unattributed"
31	
32		// headerMax is internal/app's headerMinHeight (unexported there): the
33		// header never shows more than this many info lines.
34		headerMax = 7
35	)
36	
37	// sumUsage prices to 8.20: the orchestrator 1 + 6 = 7.00 on model-a, the coder
38	// 1.20 on model-b. With Billed 10.00 the unattributed part is 1.80 (criterion 5).
39	func sumUsage(b agentusage.Billed) agentusage.Usage {
40		return agentusage.Usage{
41			Billed: b,
42			Agents: []agentusage.Agent{
43				byModel(agentusage.Agent{Main: true},
44					mu("model-a", agentusage.Tokens{Input: million, Output: 600_000}, 0)),
45				byModel(agentusage.Agent{ID: "a01", Type: "coder"},
46					mu("model-b", agentusage.Tokens{Output: 60_000}, 0)),
47			},
48		}
49	}
50	
51	func billed(usd float64) agentusage.Billed { return agentusage.Billed{USD: usd, Known: true} }
52	
53	// headerEntry returns the header entry of key, if any.
54	func headerEntry(m Model, key string) (shortcut.HeaderInfo, bool) {
55		for _, h := range m.GetHeaderInfo("") {
56			if h.Key == key {
57				return h, true
58			}
59		}
60		return shortcut.HeaderInfo{}, false
61	}
62	
63	func headerKeys(m Model) []string {
64		var keys []string
65		for _, h := range m.GetHeaderInfo("") {
66			keys = append(keys, h.Key)
67		}
68		return keys
69	}
