71	func TestWithRowsStoresTheCostSummary(t *testing.T) {
72		m := atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(10)))
73		if len(m.cost.Agents) != 2 {
74			t.Fatalf("cost.Agents = %d estimates, want 2 (same order as Usage.Agents)", len(m.cost.Agents))
75		}
76		if !m.cost.Billed.Known || m.cost.Billed.USD != 10 {
77			t.Errorf("cost.Billed = %+v, want {10 true}", m.cost.Billed)
78		}
79		if !m.cost.UnattributedKnown || math.Abs(m.cost.Unattributed-1.80) > 1e-9 {
80			t.Errorf("cost.Unattributed = %v (known %v), want 1.80 (criterion 5)", m.cost.Unattributed, m.cost.UnattributedKnown)
81		}
82	
83		// Every rebuild refreshes it: a later read changes the figures.
84		m = m.withRows(sumUsage(agentusage.Billed{}), false)
85		if m.cost.Billed.Known || m.cost.UnattributedKnown {
86			t.Errorf("after a read with no cost-state, cost = %+v, want Billed and Unattributed unknown", m.cost)
87		}
88	}
