90	func TestHeaderCostFields(t *testing.T) {
91		unpriced := sumUsage(billed(10))
92		unpriced.Agents = append(unpriced.Agents, byModel(agentusage.Agent{ID: "a02", Type: "tester"},
93			mu("model-z", agentusage.Tokens{Output: 5}, 0))) // no rate for model-z
94		noTokens := agentusage.Usage{Billed: billed(3.5), Agents: []agentusage.Agent{
95			{Main: true}, {ID: "a01", Type: "coder"},
96		}}
97	
98		tests := []struct {
99			name string
100			u    agentusage.Usage
101			want map[string]string // key -> value; "" means the entry must be absent
102		}{
103			{"criterion 5: 10.00 billed, 8.20 estimated, 1.80 unattributed", sumUsage(billed(10)),
104				map[string]string{estKey: "~$8.20", billedKey: "$10.00", unattributedKey: "$1.80"}},
105			{"criterion 6: a running session has neither Billed nor Unattributed", sumUsage(agentusage.Billed{}),
106				map[string]string{estKey: "~$8.20", billedKey: "", unattributedKey: ""}},
107			{"a stale price table: negative remainder, real minus sign", sumUsage(billed(7.80)),
108				map[string]string{estKey: "~$8.20", billedKey: "$7.80", unattributedKey: "\u2212$0.40"}},
109			{"one unpriced agent: Est. cost and Unattributed are dashes, Billed stays", unpriced,
110				map[string]string{estKey: "-", billedKey: "$10.00", unattributedKey: "-"}},
111			{"unpriced and no cost-state: still neither Billed nor Unattributed", func() agentusage.Usage {
112				u := unpriced
113				u.Billed = agentusage.Billed{}
114				return u
115			}(), map[string]string{estKey: "-", billedKey: "", unattributedKey: ""}},
116			{"no agent has tokens: Unattributed is the whole bill", noTokens,
117				map[string]string{estKey: "-", billedKey: "$3.50", unattributedKey: "$3.50"}},
118		}
119		for _, tt := range tests {
120			t.Run(tt.name, func(t *testing.T) {
121				m := atPricedAgents(t, cfgWith(t, pricesYAML), 160, tt.u)
122				for key, want := range tt.want {
123					h, ok := headerEntry(m, key)
124					switch {
125					case want == "" && ok:
126						t.Errorf("%s = %q, want no such entry", key, h.Value)
127					case want != "" && !ok:
128						t.Errorf("no %q entry in %v, want %q", key, headerKeys(m), want)
129					case want != "" && h.Value != want:
130						t.Errorf("%s = %q, want %q", key, h.Value, want)
131					}
132				}
133				if h, ok := headerEntry(m, billedKey); ok && strings.Contains(h.Value, "~") {
134					t.Errorf("Billed = %q: it is Claude Code's own figure, no estimate mark", h.Value)
135				}
136			})
137		}
138	}
