148	func TestANegativeUnattributedIsOrangeAndTheRestIsNot(t *testing.T) {
149		orange := lipgloss.TerminalColor(theme.ColorSeverityMedium)
150		normal := theme.HeaderValueStyle.GetForeground()
151	
152		neg := atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(7.80)))
153		h, ok := headerEntry(neg, unattributedKey)
154		if !ok {
155			t.Fatal("no Unattributed entry")
156		}
157		if got := h.Style.GetForeground(); got != orange {
158			t.Errorf("negative Unattributed foreground = %v, want ColorSeverityMedium %v", got, orange)
159		}
160		if strings.Contains(h.Value, "\x1b") {
161			t.Errorf("Value %q must be plain text: the color is the Style's", h.Value)
162		}
163	
164		pos := atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(10)))
165		for _, key := range []string{estKey, billedKey, unattributedKey} {
166			h, _ := headerEntry(pos, key)
167			if got := h.Style.GetForeground(); got == orange || got != normal {
168				t.Errorf("%s foreground = %v, want the ordinary header value color %v", key, got, normal)
169			}
170		}
171	}
