173	// H7: Est. cost sums the visible rows, like Tokens; Billed and Unattributed
174	// are facts of the session and ignore the filter.
175	func TestEstCostFollowsTheFilterButBilledDoesNot(t *testing.T) {
176		filtered := func(t *testing.T, m Model, query string) Model {
177			t.Helper()
178			m = send(t, m, testutil.Key("/"))
179			for _, k := range testutil.Type(query) {
180				m = feed(t, m, k)
181			}
182			return send(t, m, testutil.Key("enter"))
183		}
184	
185		m := atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(10)))
186		m = filtered(t, m, "coder")
187		for key, want := range map[string]string{estKey: "~$1.20", billedKey: "$10.00", unattributedKey: "$1.80"} {
188			if got := headerValue(t, m, key); got != want {
189				t.Errorf("filter coder: %s = %q, want %q", key, got, want)
190			}
191		}
192	
193		// A filter hiding the unpriced row gives the sum of the rest.
194		u := sumUsage(agentusage.Billed{})
195		u.Agents = append(u.Agents, byModel(agentusage.Agent{ID: "a02", Type: "tester"},
196			mu("model-z", agentusage.Tokens{Output: 5}, 0)))
197		all := atPricedAgents(t, cfgWith(t, pricesYAML), 160, u)
198		if got := headerValue(t, all, estKey); got != "-" {
199			t.Errorf("unpriced row visible: Est. cost = %q, want -", got)
200		}
201		if got := headerValue(t, filtered(t, all, "orchestrator"), estKey); got != "~$7.00" {
202			t.Errorf("filter hiding the unpriced row: Est. cost = %q, want ~$7.00", got)
203		}
204	}
