206	// The header holds headerMax lines (internal/app headerMinHeight). Before
207	// DEVDESK-47 the agents level used 3 (+ Idle); with Est. cost, Billed and
208	// Unattributed the worst case is exactly 7, so the plan (Q1 = A) leaves no
209	// room for another field.
210	func TestTheHeaderNeverExceedsSevenLines(t *testing.T) {
211		tn := time.Now()
212		u := sumUsage(billed(10))
213		u.Agents[1] = stamped(withState(u.Agents[1], agentusage.StateUnfinished), 1, tn.Add(-time.Hour), tn.Add(-20*time.Minute))
214	
215		cfg := cfgWith(t, pricesYAML)
216		m := atPricedAgentsAt(t, cfg, u, statusClock{now: tn, alive: true})
217		if got := headerValue(t, m, "Idle"); got != "1" {
218			t.Fatalf("precondition: Idle = %q, want 1", got)
219		}
220		keys := headerKeys(m)
221		if len(keys) != headerMax {
222			t.Errorf("worst case has %d entries %v, want exactly %d", len(keys), keys, headerMax)
223		}
224		if keys[len(keys)-1] != "Idle" {
225			t.Errorf("Idle stays last, got %v", keys)
226		}
227	
228		// Unpriced or unknown Billed only ever remove entries or keep the count.
229		for name, mm := range map[string]Model{
230			"no prices":  atPricedAgentsAt(t, nil, u, statusClock{now: tn, alive: true}),
231			"no billing": atPricedAgentsAt(t, cfg, withBilled(u, agentusage.Billed{}), statusClock{now: tn, alive: true}),
232		} {
233			if n := len(mm.GetHeaderInfo("")); n > headerMax {
234				t.Errorf("%s: %d header entries, max %d", name, n, headerMax)
235			}
236		}
237	}
