244	// atPricedAgentsAt is atPricedAgents with the activity clock set before the answer.
245	func atPricedAgentsAt(t *testing.T, cfg *config.Config, u agentusage.Usage, c statusClock) Model {
246		t.Helper()
247		isolate(t)
248		m := feed(t, New(cfg), testutil.Resize(160, 20))
249		s := session("id-a000000-0000", "/srv/pa", 0)
250		s.Parent = "/p/a.jsonl"
251		m = loaded(t, m, s)
252		m, _ = opened(t, m, "right")
253		m.clock = c
254		return answer(t, m, u)
255	}
