257	// A delta that brings the cost-state makes Billed appear with no ctrl+r, and a
258	// line written after it takes it away again (the session was resumed).
259	func TestBilledAppearsWhenTheCostStateIsAppended(t *testing.T) {
260		m, parent := atFixture(t)
261		if _, ok := headerEntry(m, billedKey); ok {
262			t.Fatal("precondition: the fixture has no cost-state, so no Billed")
263		}
264	
265		appendLine(t, parent, `{"type":"cost-state","totalCostUSD":10}`)
266		m, msgs := pollTick(t, m, m.agentGen)
267		reads := usageMsgs(msgs)
268		if len(reads) != 1 {
269			t.Fatalf("precondition: one read, got %+v", msgs)
270		}
271		m, _ = answered(t, m, reads[0])
272		if got := headerValue(t, m, billedKey); got != "$10.00" {
273			t.Errorf("Billed = %q after the cost-state arrived, want $10.00", got)
274		}
275	
276		appendLine(t, parent, usageLine("msg_resumed", "model-alpha", 1, 2))
277		m, msgs = pollTick(t, m, m.agentGen)
278		reads = usageMsgs(msgs)
279		if len(reads) != 1 {
280			t.Fatalf("precondition: one read, got %+v", msgs)
281		}
282		m, _ = answered(t, m, reads[0])
283		if v, ok := headerEntry(m, billedKey); ok {
284			t.Errorf("a line after the cost-state: Billed = %q, want it gone (criterion 6)", v.Value)
285		}
286	}
