292	func threeUnpriced() agentusage.Usage {
293		return agentusage.Usage{Agents: []agentusage.Agent{
294			byModel(agentusage.Agent{Main: true}, mu("model-a", agentusage.Tokens{Output: 1}, 0)),
295			byModel(agentusage.Agent{ID: "a01", Type: "coder"}, mu("model-e", agentusage.Tokens{Output: 1}, 0)),
296			byModel(agentusage.Agent{ID: "a02", Type: "tester"}, mu("model-c", agentusage.Tokens{Output: 1}, 0)),
297			byModel(agentusage.Agent{ID: "a03", Type: "writer"}, mu("model-d", agentusage.Tokens{Output: 1}, 0)),
298		}}
299	}
