301	func TestFooterPriceHint(t *testing.T) {
302		tests := []struct {
303			name     string
304			cfg      *config.Config
305			u        agentusage.Usage
306			contains []string
307			excludes []string
308		}{
309			{"empty table, session with tokens: say where to set prices", nil, sumUsage(billed(1)),
310				[]string{pricesKey, "?"}, nil},
311			{"default config is an empty table too", config.Default(), sumUsage(billed(1)),
312				[]string{pricesKey}, nil},
313			{"one model without a rate is named", cfgWith(t, pricesYAML),
314				byModel1(sumUsage(billed(1)), "model-z"), []string{"model-z", pricesKey}, nil},
315			{"three models without a rate: the first (sorted) and a count", cfgWith(t, pricesYAML), threeUnpriced(),
316				[]string{"model-c", "2 more models", pricesKey}, []string{"model-d", "model-e"}},
317			{"everything priced: nothing", cfgWith(t, pricesYAML), sumUsage(billed(1)), nil, []string{pricesKey}},
318			{"empty table but no tokens at all: nothing to estimate, nothing said", nil,
319				agentusage.Usage{Agents: []agentusage.Agent{{Main: true}, {ID: "a01", Type: "coder"}}}, nil, []string{pricesKey}},
320		}
321		for _, tt := range tests {
322			t.Run(tt.name, func(t *testing.T) {
323				m := atPricedAgents(t, tt.cfg, 160, tt.u)
324				st := m.status()
325				for _, w := range tt.contains {
326					if !strings.Contains(st.Text, w) {
327						t.Errorf("status %q lacks %q", st.Text, w)
328					}
329				}
330				for _, w := range tt.excludes {
331					if strings.Contains(st.Text, w) {
332						t.Errorf("status %q must not contain %q", st.Text, w)
333					}
334				}
335				if len(tt.contains) > 0 {
336					if st.Level != sharedcomponents.LevelInfo || st.Spinner {
337						t.Errorf("the hint is a plain Info line (nothing failed, nothing is waiting), got %+v", st)
338					}
339					if !strings.Contains(stripANSI(footerText(m)), tt.contains[0]) {
340						t.Errorf("RenderFooter lacks %q:\n%s", tt.contains[0], footerText(m))
341					}
342				} else if st.Text != "" {
343					t.Errorf("status = %+v, want none", st)
344				}
345			})
346		}
347	}
