349	// byModel1 returns u with one more sub-agent whose only tokens are under model.
350	func byModel1(u agentusage.Usage, model string) agentusage.Usage {
351		u.Agents = append(append([]agentusage.Agent{}, u.Agents...),
352			byModel(agentusage.Agent{ID: "a09", Type: "extra"}, mu(model, agentusage.Tokens{Output: 3}, 0)))
353		return u
354	}
