356	// Rule 128: the hint is a state derived on every frame, not a timed event.
357	func TestThePriceHintIsAStateNotAMessage(t *testing.T) {
358		m := atPricedAgents(t, nil, 160, sumUsage(billed(1)))
359		if !strings.Contains(m.status().Text, pricesKey) {
360			t.Fatalf("precondition: no hint in %+v", m.status())
361		}
362		m = feed(t, m, sharedcomponents.ClearFooterMsg{ID: m.footer.ID()})
363		if !strings.Contains(stripANSI(footerText(m)), pricesKey) {
364			t.Errorf("the hint went away with a footer expiry, it is not a message:\n%s", footerText(m))
365		}
366		// Once priced it is gone on the very next rebuild: no stale text.
367		priced := atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(1)))
368		if priced.status().Text != "" {
369			t.Errorf("status = %+v with every model priced", priced.status())
370		}
371	}
