373	func TestPriceHintPrecedence(t *testing.T) {
374		u := sumUsage(billed(1))
375		u.Diagnostics.UnreadableLines = 2
376	
377		m := atPricedAgents(t, nil, 160, u)
378		if st := m.status(); st.Level != sharedcomponents.LevelWarning || !strings.Contains(st.Text, "approximate") {
379			t.Errorf("degraded + hint = %+v, want the approximate warning first", st)
380		}
381		m.agentsLoading = true
382		if st := m.status(); !st.Spinner || strings.Contains(st.Text, pricesKey) {
383			t.Errorf("loading + hint = %+v, want the spinner line", st)
384		}
385		m.agentsErr = true
386		if st := m.status(); st.Level != sharedcomponents.LevelError || strings.Contains(st.Text, pricesKey) {
387			t.Errorf("error + hint = %+v, want the error", st)
388		}
389	}
