407	func TestCostFieldsAddNoShortcutAndChangeNoText(t *testing.T) {
408		want := []string{"ctrl+r", openKey, closeKey, "/", ".", "?"}
409		for name, m := range map[string]Model{
410			"no prices":   atPricedAgents(t, nil, 160, sumUsage(billed(10))),
411			"priced":      atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(10))),
412			"not billed":  atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(agentusage.Billed{})),
413			"unpriced":    atPricedAgents(t, cfgWith(t, pricesYAML), 160, threeUnpriced()),
414			"stale table": atPricedAgents(t, cfgWith(t, pricesYAML), 160, sumUsage(billed(7.8))),
415		} {
416			if got := testutil.ShortcutKeys(m.GetShortcuts()); strings.Join(got, ",") != strings.Join(want, ",") {
417				t.Errorf("%s: keys %v, want %v", name, got, want)
418			}
419		}
420		descriptions := map[string]string{
421			"ctrl+r": "Refresh", openKey: "Open agents", closeKey: "Go back", "/": "Filter", ".": "Sort", "?": "Help",
422		}
423		for _, sc := range atPricedAgents(t, nil, 160, sumUsage(billed(10))).GetShortcuts() {
424			if sc.Description != descriptions[sc.Key] {
425				t.Errorf("%s description = %q, want %q (unchanged)", sc.Key, sc.Description, descriptions[sc.Key])
426			}
