432	func TestFormatUSDDegenerateAmounts(t *testing.T) {
433		tests := []struct {
434			name string
435			in   float64
436			want string
437		}{
438			{"NaN", math.NaN(), "-"},
439			{"+Inf", math.Inf(1), "-"},
440			{"-Inf", math.Inf(-1), "-"},
441			{"negative under half a cent", -0.004, "\u2212<$0.01"},
442			{"negative tiny", -1e-9, "\u2212<$0.01"},
443			{"negative half a cent", -0.005, "\u2212$0.01"},
444			{"negative whole dollars", -1234.5, "\u2212$1235"},
445			{"negative saturated", -123456, "\u2212$99999+"},
446			{"largest finite float saturates", math.MaxFloat64, "$99999+"},
447			{"negative largest finite float", -math.MaxFloat64, "\u2212$99999+"},
448		}
449		for _, tt := range tests {
450			t.Run(tt.name, func(t *testing.T) {
451				got := formatUSD(tt.in)
452				if got != tt.want {
453					t.Errorf("formatUSD(%v) = %q, want %q", tt.in, got, tt.want)
454				}
455				if strings.ContainsAny(got, "NI") || strings.Contains(got, "\x1b") {
456					t.Errorf("formatUSD(%v) = %q leaks a float spelling or ANSI", tt.in, got)
457				}
458			})
459		}
460	}
