475	func TestHelpDescribesCosts(t *testing.T) {
476		body := costsHelp(t)
477		lower := strings.ToLower(body)
478		for _, want := range []string{
479			"est. cost", "estimate", "~", "\u2265 ~", // the estimate mark and the sub-agent floor
480			"dash",                               // an unknown rate shows a dash, never zero
481			"billed", "unattributed", "negative", // criterion 5, and the stale-table signal
482			"no tokens",              // no agent with tokens: Unattributed is the whole bill
483			"web search",             // what is never priced (H9)
484			pricesKey, "per million", // where, and in what unit
485			"input", "output", "cache_write_5m", "cache_write_1h", "cache_read", // the five rates
486			"case-insensitive", "yyyymmdd", // the matching rule
487			"restart", "context", // when prices are read again
488		} {
489			if !strings.Contains(lower, strings.ToLower(want)) {
490				t.Errorf("the Costs section should mention %q:\n%s", want, body)
491			}
492		}
493		if !strings.Contains(lower, "ctrl+r") {
494			t.Errorf("the Costs section should say ctrl+r does not re-read the prices:\n%s", body)
495		}
496	}
497	
498	// The example is meant to be pasted: it must load, and every rate must be a number.
499	func TestTheHelpYAMLExampleLoadsAndIsComplete(t *testing.T) {
500		var block []string
501		in := false
502		for _, line := range strings.Split(costsHelp(t), "\n") {
503			switch {
504			case strings.HasPrefix(line, "agent_usage:"):
505				in = true
506				block = append(block, line)
507			case in && (strings.HasPrefix(line, " ") || strings.HasPrefix(line, "\t")):
508				block = append(block, line)
509			case in:
510				in = false
511			}
512		}
513		if len(block) == 0 {
514			t.Fatal("the Costs section needs a YAML example starting at a line `agent_usage:`")
515		}
516		var doc struct {
517			AgentUsage config.AgentUsageConfig `yaml:"agent_usage"`
518		}
519		if err := yaml.Unmarshal([]byte(strings.Join(block, "\n")), &doc); err != nil {
520			t.Fatalf("the example is not valid YAML: %v\n%s", err, strings.Join(block, "\n"))
521		}
522		if len(doc.AgentUsage.Prices) == 0 {
523			t.Fatalf("the example holds no model:\n%s", strings.Join(block, "\n"))
524		}
525		table, problems := pricing.FromConfig(doc.AgentUsage.Prices)
526		if len(problems) > 0 || table.Len() != len(doc.AgentUsage.Prices) {
527			t.Errorf("pasting the example gives problems %+v and %d usable models of %d (all five rates are required)",
528				problems, table.Len(), len(doc.AgentUsage.Prices))
529		}
530	}
531	
532	// Review carry-over: the narrow-terminal sentence of the help must follow the
533	// real drop order, which now includes Est. cost (right after Cache write).
534	func TestHelpDropOrderMentionsEstCost(t *testing.T) {
535		var body string
536		for _, s := range New(nil).GetHelpContent().Sections {
537			if s.Title == "Agent columns" {
538				body = s.Body
539			}
540		}
541		i := strings.Index(body, "On a narrow terminal")
542		if i < 0 {
543			t.Fatalf("the Agent columns section lost its narrow-terminal sentence:\n%s", body)
544		}
545		sentence := body[i:]
546		write, est, read := strings.Index(sentence, "Cache write"), strings.Index(sentence, "Est. cost"), strings.Index(sentence, "Cache read")
547		if est < 0 || write < 0 || read < 0 || !(write < est && est < read) {
548			t.Errorf("drop order must read Cache write, Est. cost, Cache read (got %d, %d, %d):\n%s", write, est, read, sentence)
549		}
550		if !strings.Contains(body, "Est. cost:") && !strings.Contains(body, "Est. cost,") {
551			t.Errorf("the Agent columns section should describe the Est. cost column:\n%s", body)
552		}
553	}
554

