138	// agentColumns describes the agents table. Only Total sorts, largest first;
139	// without a sort the order is the tree. Columns give way on a narrow terminal
140	// in this order: Cache write, Est. cost, Cache read, In, Model, Duration, Tools, State
141	// (Cache write and Est. cost are DropFirst, the rightmost first). Est. cost is visible
142	// from 126 columns. The ID never gives way, so two agents of one type stay apart.
143	func agentColumns() []datatable.Column[agentRow] {
144		count := func(title string, width int, tokens func(agentRow) int64) datatable.Column[agentRow] {
145			return datatable.Column[agentRow]{
146				Title: title, Sizing: datatable.SizingFixed, MinWidth: width,
147				Cell:  func(r agentRow) string { return formatTokens(tokens(r)) },
148				Style: func(r agentRow) lipgloss.Style { return dimWhen(tokens(r) == 0) },
149			}
150		}
151		in := count("In", 6, func(r agentRow) int64 { return r.Tokens.Input })
152		in.Optional = true
153		cacheRead := count("Cache read", len("Cache read"), func(r agentRow) int64 { return r.Tokens.CacheRead })
154		cacheRead.Optional = true
155		cacheWrite := count("Cache write", len("Cache write"), func(r agentRow) int64 { return r.Tokens.CacheWrite })
156		cacheWrite.Optional, cacheWrite.DropFirst = true, true
157		total := count("Total", 6, func(r agentRow) int64 { return r.Tokens.Total() })
158		total.Less = func(a, b agentRow) bool { return a.Tokens.Total() < b.Tokens.Total() }
159		total.DescFirst = true
160	
161		out := count("Out", 7, nil)
162		out.Cell = outCell
163		out.Style = func(r agentRow) lipgloss.Style { return dimWhen(r.Tokens.Output == 0) }
164	
165		return []datatable.Column[agentRow]{
166			{Title: "Agent", Sizing: datatable.SizingContent, MinWidth: 14, Cell: roleCell, Search: agentSearch,
167				Style: func(r agentRow) lipgloss.Style { return dimWhen(!r.Main && r.Type == "") }},
168			{Title: "ID", Sizing: datatable.SizingContent, MinWidth: agentIDPrefix, Cell: idCell,
169				Search: func(r agentRow) string { return r.ID },
170				Style:  func(r agentRow) lipgloss.Style { return dimWhen(idCell(r) == noValue || idCell(r) == unknownID) }},
171			costColumn(), stateColumn(), toolsColumn(), durationColumn(),
172			{Title: "Model", Sizing: datatable.SizingContent, MinWidth: 12, Flex: 2, Optional: true, Cell: modelsCell, Search: modelsCell,
173				Style: func(r agentRow) lipgloss.Style { return dimWhen(len(r.Models) == 0) }},
174			in, out, cacheRead, cacheWrite, total,
175			{Title: "Share", Sizing: datatable.SizingFixed, MinWidth: len("100.0%"), Cell: shareCell,
176				Style: func(r agentRow) lipgloss.Style { return dimWhen(r.share <= 0) }},
177		}
178	}
179	
180	// stateColumn is the State column: the label is searchable, so `/idle` keeps
181	// the idle agents. Idle is the one state that reads as a warning.
