17	const (
18		// noValue is the dash of a cell with nothing to show.
19		noValue = "-"
20		// noModel stands for an agent whose transcript named no model.
21		noModel = noValue
22		// unknownID stands for a sub-agent whose ID is empty, so it cannot be
23		// mistaken for the orchestrator, which has no short ID by design.
24		unknownID = "?"
25		// unknownType stands for a sub-agent whose meta file gave no type.
26		unknownType = "unknown"
27		// orchestratorLabel is the Agent cell of the main agent.
28		orchestratorLabel = "orchestrator"
29		// partialMark prefixes an output count that is a floor, not an exact value.
30		partialMark = "≥ "
31		// stem and lastStem draw the tree branch in front of a sub-agent's type.
32		stem     = "├─ "
33		lastStem = "└─ "
34	)
