39	// agentRow is one line of the agents table.
40	type agentRow struct {
41		agentusage.Agent
42		branch  string   // stem, lastStem, or "" (orchestrator, or a sorted list)
43		shortID string   // ID prefix, distinct within the session; "" for the orchestrator
44		share   int      // tenths of a percent of the session total, or noShare
45		key     string   // identity across rebuilds, see agentKeys
46		state   runState // what the State column shows
47		cost    pricing.Estimate
48	}
