101	// shortAgentIDs cuts every ID to one common length, the smallest n >=
102	// agentIDPrefix (in runes) at which all of them differ, capped at each ID's
103	// own length.
104	func shortAgentIDs(ids []string) []string {
105		if len(ids) == 0 {
106			return nil
107		}
108		longest := 0
109		runes := make([][]rune, len(ids))
110		for i, id := range ids {
111			runes[i] = []rune(id)
112			longest = max(longest, len(runes[i]))
113		}
114		cut := func(n int) []string {
115			out := make([]string, len(runes))
116			for i, r := range runes {
117				out[i] = string(r[:min(n, len(r))])
118			}
119			return out
120		}
121		for n := agentIDPrefix; n < longest; n++ {
122			seen := make(map[string]bool, len(ids))
123			distinct := true
124			for _, s := range cut(n) {
125				if seen[s] {
126					distinct = false
127					break
128				}
129				seen[s] = true
130			}
131			if distinct {
132				return cut(n)
133			}
134		}
135		return cut(longest)
136	}
