243	// shareCell is the Share column.
244	func shareCell(r agentRow) string { return formatShare(r.share) }
245	
246	// roleCell is the Agent cell: "orchestrator", or the sub-agent's type behind
247	// its branch.
248	func roleCell(r agentRow) string {
249		if r.Main {
250			return orchestratorLabel
251		}
252		typ := r.Type
253		if typ == "" {
254			typ = unknownType
255		}
256		return r.branch + typ
