1	package agentusageview
2	
3	import (
4		"time"
5	
6		"github.com/anthnel/devdesk/internal/agentusage"
7	)
8	
9	// runState is what the State column shows for an agent.
10	type runState int
11	
12	const (
13		stateUnknown runState = iota
14		stateRunning
15		stateIdle
16		stateDone
17	)
18	
19	// label returns the text shown in the State column.
20	func (s runState) label() string {
21		switch s {
22		case stateRunning:
23			return "running"
24		case stateIdle:
25			return "idle"
26		case stateDone:
27			return "done"
28		default:
29			return "unknown"
30		}
31	}
32	
33	// statusClock is what the states are computed against: when the last read
34	// finished, and whether the session counts as alive (not Settled).
35	type statusClock struct {
36		now   time.Time
37		alive bool
38	}
39	
40	// quiet reports whether the agent has been silent for strictly more than
41	// idleAfter. An agent with no timestamp, or one stamped in the future, is
42	// never quiet.
43	func (c statusClock) quiet(a agentusage.Agent) bool {
44		if a.LastActivity.IsZero() {
45			return false
46		}
47		return c.now.Sub(a.LastActivity) > idleAfter
48	}
49	
50	// running is the state of an agent that has not finished: running, or idle
51	// once it has been silent for long enough.
52	func (c statusClock) running(a agentusage.Agent) runState {
53		if c.quiet(a) {
54			return stateIdle
55		}
56		return stateRunning
57	}
58	
59	// subAgentState is the state of one sub-agent. A finished one is done; an
60	// unfinished one is running or idle whether or not the session is alive; one
61	// whose meta says nothing is judged the same way while the session is alive,
62	// and is unknown once it is not.
63	func (c statusClock) subAgentState(a agentusage.Agent) runState {
64		switch {
65		case a.State == agentusage.StateFinished:
66			return stateDone
67		case a.State == agentusage.StateUnfinished || c.alive:
68			return c.running(a)
69		default:
70			return stateUnknown
71		}
72	}
73	
74	// orchestratorState is the state of the orchestrator, which no file says is
75	// finished: unknown when the session is not alive, idle only if it has been
76	// silent for long enough and no sub-agent is running, running otherwise.
77	func (c statusClock) orchestratorState(a agentusage.Agent, subRunning bool) runState {
78		if !c.alive {
79			return stateUnknown
80		}
81		if subRunning {
82			return stateRunning
83		}
84		return c.running(a)
85	}
86	
87	// agentStates returns one state per agent, same order. It is pure: the
88	// clock is a parameter.
89	func agentStates(agents []agentusage.Agent, c statusClock) []runState {
90		out := make([]runState, len(agents))
91		subRunning := false
92		for i, a := range agents {
93			if a.Main {
94				continue
95			}
96			out[i] = c.subAgentState(a)
97			subRunning = subRunning || out[i] == stateRunning
98		}
99		for i, a := range agents {
100			if a.Main {
101				out[i] = c.orchestratorState(a, subRunning)
102			}
103		}
104		return out
105	}
