1	package pricing
2	
3	import (
4		"math"
5		"sort"
6	
7		"github.com/anthnel/devdesk/internal/agentusage"
8	)
9	
10	// noModelLabel names the bucket of tokens recorded under no model.
11	const noModelLabel = "(no model)"
12	
13	// Status tells what an Estimate holds.
14	type Status int
15	
16	const (
17		// NoTokens means there was nothing to price; USD is 0 and means nothing.
18		NoTokens Status = iota
19		// Priced means every model with tokens has a rate; USD is the cost.
20		Priced
21		// Unpriced means at least one model with tokens has no rate. USD is 0 and
22		// must not be shown: a partial sum would under-state without saying so.
23		Unpriced
24	)
25	
26	// Estimate is the indicative cost of an agent, or of a sum of agents.
27	type Estimate struct {
28		USD    float64
29		Status Status
30		// Unpriced lists the models with tokens and no rate, in first-appearance
31		// order; the bucket of no model is "(no model)".
32		Unpriced []string
33	}
34	
35	// Cost returns the cost in USD of one model's tokens. The 5 minute cache
36	// write is the total write minus its 1 hour part.
37	func (r Rates) Cost(m agentusage.ModelUsage) float64 {
38		t := m.Tokens
39		return (float64(t.Input)*r.Input +
40			float64(t.Output)*r.Output +
41			float64(m.CacheWrite5m())*r.CacheWrite5m +
42			float64(m.CacheWrite1h)*r.CacheWrite1h +
43			float64(t.CacheRead)*r.CacheRead) / perMillion
44	}
45	
46	// hasTokens reports whether a model bucket carries any token.
47	func hasTokens(m agentusage.ModelUsage) bool {
48		t := m.Tokens
49		return t.Input != 0 || t.Output != 0 || t.CacheRead != 0 || t.CacheWrite != 0
50	}
51	
52	// Agent estimates one agent. It never returns a partial cost: one model with
53	// tokens and no rate makes the whole agent Unpriced.
54	func (t Table) Agent(a agentusage.Agent) Estimate {
55		var e Estimate
56		buckets := a.ByModel
57		if len(buckets) == 0 && a.Tokens != (agentusage.Tokens{}) {
58			// Tokens without a split cannot be priced per model.
59			buckets = []agentusage.ModelUsage{{Tokens: a.Tokens}}
60		}
61		for _, m := range buckets {
62			if !hasTokens(m) {
63				continue
64			}
65			e.Status = Priced
66			r, ok := t.Lookup(m.Model)
67			if !ok {
68				e.Unpriced = appendOnce(e.Unpriced, modelLabel(m.Model))
69				continue
70			}
71			cost := r.Cost(m)
72			if !isFinite(cost) {
73				// A huge rate times a huge count is not a cost worth showing.
74				e.Unpriced = appendOnce(e.Unpriced, modelLabel(m.Model))
75				continue
76			}
77			e.USD += cost
78		}
79		if len(e.Unpriced) > 0 || !isFinite(e.USD) {
80			return Estimate{Status: Unpriced, Unpriced: e.Unpriced}
81		}
82		return e
83	}
84	
85	// isFinite reports whether f is neither NaN nor an infinity.
86	func isFinite(f float64) bool { return !math.IsNaN(f) && !math.IsInf(f, 0) }
87	
88	func modelLabel(model string) string {
89		if model == "" {
90			return noModelLabel
91		}
92		return model
93	}
94	
95	func appendOnce(list []string, s string) []string {
96		for _, x := range list {
97			if x == s {
98				return list
99			}
100		}
101		return append(list, s)
102	}
103	
104	// Sum adds estimates: Unpriced if any is, NoTokens if all are.
105	func Sum(es []Estimate) Estimate {
106		var out Estimate
107		for _, e := range es {
108			switch e.Status {
109			case Priced:
110				out.USD += e.USD
111				if out.Status == NoTokens {
112					out.Status = Priced
113				}
114			case Unpriced:
115				out.Status = Unpriced
116				for _, m := range e.Unpriced {
117					out.Unpriced = appendOnce(out.Unpriced, m)
118				}
119			}
120		}
121		if !isFinite(out.USD) {
122			// The sum of finite estimates can still overflow.
123			out.Status = Unpriced
124		}
125		if out.Status == Unpriced {
126			out.USD = 0
127		}
128		return out
129	}
130	
131	// Summary is the cost picture of a whole session.
132	type Summary struct {
133		Agents []Estimate // same order as Usage.Agents
134		Billed agentusage.Billed
135		// Unattributed is Billed minus the agents' estimates; it may be negative
136		// (the price table is higher than what was recorded). It is meaningful
137		// only when UnattributedKnown.
138		Unattributed      float64
139		UnattributedKnown bool
140		Unpriced          []string // sorted, distinct, over the whole session
141	}
142	
143	// Session estimates every agent of a session. Unattributed is known only when
144	// Billed is known and every agent with tokens is priced.
145	func (t Table) Session(u agentusage.Usage) Summary {
146		s := Summary{Agents: make([]Estimate, len(u.Agents)), Billed: u.Billed}
147		for i, a := range u.Agents {
148			s.Agents[i] = t.Agent(a)
149		}
150		total := Sum(s.Agents)
151		s.Unpriced = total.Unpriced
152		sort.Strings(s.Unpriced)
153		if u.Billed.Known && total.Status != Unpriced {
154			s.Unattributed = u.Billed.USD - total.USD
155			s.UnattributedKnown = true
156		}
157		return s
158	}
